11	// --- configuration delivery -------------------------------------------------
12	
13	// configPublishRequest is the raw publish envelope. Config is decoded a second
14	// time as a generic JSON value so a non-object body is rejected even though the
15	// bytes themselves are valid JSON.
16	type configPublishRequest struct {
17		RequestID   string          `json:"requestId"`
