79	// ever returned; 204 (with empty body) means up to date or never published.
80	func (h *handler) pendingConfig(w http.ResponseWriter, r *http.Request) {
81		view, ok, err := h.store.PendingConfig(r.PathValue("id"))
82		if errors.Is(err, ErrDeviceNotFound) {
83			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
84			return
85		}
86		if err != nil {
87			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
88			return
89		}
90		if !ok {
91			w.WriteHeader(http.StatusNoContent)
92			return
93		}
