98		var request configReceiptRequest
99		if err := decodeSingleJSON(r, &request); err != nil {
100			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
101			return
102		}
103		receiptID := strings.TrimSpace(request.ReceiptID)
104		if receiptID == "" {
105			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "receiptId is required"})
106			return
107		}
108		if request.Version < 1 {
109			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "version must be a positive integer"})
110			return
111		}
