123		if errors.Is(err, ErrDeviceNotFound) {
124			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
125			return
126		}
127		if errors.Is(err, ErrConfigVersionUnknown) {
128			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
