306		status.TargetVersion = int64(len(cfg.versions))
307		status.AppliedVersion = cfg.applied
308		for i := len(cfg.receipts) - 1; i >= 0; i-- {
309			receipt := cfg.receipts[i]
310			if !receipt.Success && receipt.Version > cfg.applied {
311				status.FailureReason = receipt.Reason
312				break
313			}
314		}
