361				if !ok || !jsonValueEqual(value, other) {
362					return false
363				}
364			}
365			return true
366		case []any:
367			bv, ok := b.([]any)
368			if !ok || len(av) != len(bv) {
369				return false
370			}
371			for i := range av {
372				if !jsonValueEqual(av[i], bv[i]) {
373					return false
374				}
375			}
