379			// float64; == is the numeric value comparison.
380			bv, ok := b.(float64)
381			return ok && av == bv
382		case string:
383			bv, ok := b.(string)
384			return ok && av == bv
385		case bool:
386			bv, ok := b.(bool)
387			return ok && av == bv
388		case nil:
389			return b == nil
390		default:
391			return false
392		}
