569		publishConfig(t, h, "gw", publishBody("r1", 0, `{"v":1}`), http.StatusCreated)
570		getPending(t, h, "gw")
571		postReceipt(t, h, "gw", receiptBody("rc-f", 1, false, "boom"), http.StatusCreated)
572		publishConfig(t, h, "gw", publishBody("r2", 1, `{"v":2}`), http.StatusCreated)
573		postReceipt(t, h, "gw", receiptBody("rc-ok", 2, true, ""), http.StatusCreated)
574	
575		snapshot := decodeBody[struct {
576			Devices []Device `json:"devices"`
577		}](t, doRequest(t, h, http.MethodGet, "/v1/fleet", ""))
578		if got := snapshot.Devices[0]; !got.LastSeenAt.Equal(telemetryAt) {
579			t.Fatalf("lastSeenAt = %s, want telemetry time %s (config ops must not refresh it)", got.LastSeenAt, telemetryAt)
580		}
581		events := allEvents(t, h, "gw")
582		if len(events) != 1 {
583			t.Fatalf("telemetry history changed: %+v", events)
584		}
585	}
