	publishConfig(t, h, "gw", publishBody("r1", 0,
		`{"big":9007199254740993,"tiny":1e-400,"frac":0.10000000000000001}`), http.StatusCreated)
	if err := store.Close(); err != nil {
		t.Fatal(err)
	}

	store2 := reopenPersistent(t, dir)
	h2 := NewHandler(store2)

