	configs := listConfigs(t, h2, "gw")
	if len(configs) != 1 ||
		string(configs[0].Config) != `{"big":9007199254740993,"tiny":1e-400,"frac":0.10000000000000001}` {
		t.Fatalf("recovered content = %+v, numbers must not be rounded", configs)
